    ('6a4a2f81-252d-5c58-9be7-b16d42762b9b'::uuid, 'Quiz — Besoin, fonctions et chaînes', 'Sciences de l’ingénieur', '1re', 'Analyser un système', '870fa58b-cbb3-56fa-b848-ad8f6ed379ec'::uuid),
