    ('907650f8-1117-5a79-a451-4719234f3ca4'::uuid, '39cf5380-3f95-58e8-ac06-ff6fe1d0e0d2'::uuid, 'Que désigne un « lexical field » ?', 'mcq', '["Un champ lexical","Un registre de langue","Un temps verbal","Une figure de style"]'::jsonb, 0, 'Son repérage nourrit le « how ».', 6),
