    ('374e399a-5789-5f25-ae99-e80dd5f85e50'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Le dépassement se lit sur…', 'mcq', '["La réponse indicielle","Le diagramme d’états","La nomenclature","Le schéma électrique"]'::jsonb, 0, 'Avec le temps de réponse à 5 % et l’erreur statique.', 6),
