    ('40bf2907-308e-5e26-b09a-c273067e8906'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Un écart entre simulation et mesure invalide forcément le modèle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut d’abord examiner les hypothèses simplificatrices retenues.', 2),
